/* MODULE ob05 · Bước 1 Quan sát · Tín hiệu hành vi: khách làm gì, không phải khách nói gì
   10 bài × 7 câu. Thương hiệu được nêu như ví dụ công khai; mọi con số là MINH HOẠ và tự khớp nhau. */
BAI_ADD({ mod:'ob05', lessons:[

/* ------------------------------------------------------------------ 01 */
{ id:'B:ob05-01', skill:'insight', read:'6 phút', t:'Khách nói thích ít đường, sao đơn vẫn toàn full đường?',
  situation:'Một chuỗi trà sữa ở Hà Nội khảo sát 500 khách: 62% trả lời "muốn đồ uống ít đường, lành mạnh hơn". Chuỗi ra dòng trà trái cây 30% đường. Sau hai tháng, dữ liệu máy POS cho thấy chỉ 9% ly bán ra chọn mức đường thấp; phần còn lại vẫn là 70–100% đường như cũ.',
  concept:{ name:'Khoảng cách nói – làm (say–do gap)',
    body:'Khi được hỏi, khách trả lời theo hình ảnh họ <b>muốn có</b> về bản thân: lành mạnh, tiết kiệm, có trách nhiệm. Khi móc ví, họ chọn theo thói quen, khẩu vị và cảm xúc lúc đó. Khảo sát đo được mong muốn; dữ liệu mua đo được hành vi. Hai thứ đều có ích, nhưng khi phải dự báo doanh số, <b>hành vi thắng lời nói</b>. Việc của marketer là tìm chỗ lệch và hỏi vì sao lệch.' },
  example:'62% nói muốn ít đường, nhưng chỉ 9% ly thật sự chọn ít đường — khoảng lệch 53 điểm phần trăm. Đọc sâu hơn: nhóm chọn ít đường tập trung ở khách văn phòng mua buổi sáng. Quyết định hợp lý không phải bỏ dòng sản phẩm, mà giữ nó cho khung giờ và nhóm khách đó, còn thực đơn chính vẫn xây quanh vị ngọt mà đa số đang thật sự trả tiền.',
  takeaway:'Khảo sát cho biết khách muốn mình là ai; hoá đơn cho biết khách thật sự là ai.',
  apply:'Tìm một câu bạn hay nói ("mình sẽ tập thể dục", "mình ít mua online") và so với dấu vết thật trong tuần qua. Nói trong 60 giây: khoảng lệch là bao nhiêu, vì sao.',
  mistakes:['Lấy tỉ lệ "muốn mua" trong khảo sát làm dự báo doanh số.','Kết luận khách nói dối, thay vì hỏi vì sao lời nói và hành vi lệch nhau.'],
  q:[
  { type:'mcq', stem:'Trước khi đọc bài: 62% khách nói muốn đồ uống ít đường. Bạn đoán bao nhiêu phần trăm ly bán ra thật sự chọn ít đường?',
    options:[{k:'a',t:'Khoảng 60%, vì khách đã nói rõ mong muốn'},{k:'b',t:'Khoảng 40%, vì một phần khách đổi ý khi đứng trước quầy'},
             {k:'c',t:'Dưới 15%, vì thói quen vị ngọt vẫn thắng'},{k:'d',t:'Khoảng 30%, vì giá dòng mới cao hơn dòng cũ'}],
    answer:'c', why:{a:'Nếu lời nói khớp hành vi thì đã không có bài học này; thực tế chỉ 9%.',
      b:'Có đổi ý, nhưng mức lệch thật lớn hơn nhiều; POS chỉ ra 9%.',
      c:'Đúng. Dữ liệu POS chỉ ra 9% — khoảng lệch nói – làm rất lớn ở các chủ đề "nên làm".',
      d:'Giá có thể ảnh hưởng, nhưng tình huống không cho thấy dòng mới đắt hơn; con số thật là 9%.'} },
  { type:'mcq', stem:'Sếp muốn đổi toàn bộ thực đơn sang ít đường vì "62% khách muốn thế". Bạn làm gì?',
    options:[{k:'a',t:'Đồng ý đổi hết, vì khảo sát 500 người là mẫu đủ lớn'},{k:'b',t:'Đưa số POS 9%, đề xuất giữ dòng ít đường cho nhóm khách sáng'},
             {k:'c',t:'Làm thêm một khảo sát lớn hơn để xác nhận con số 62%'},{k:'d',t:'Bỏ dòng ít đường vì 9% là quá thấp để duy trì'}],
    answer:'b', why:{a:'Mẫu lớn không sửa được việc câu hỏi đo mong muốn chứ không đo hành vi mua.',
      b:'Đúng. Dựa vào hành vi đã quan sát, phục vụ đúng nhóm đang mua thay vì đảo cả thực đơn.',
      c:'Khảo sát lớn hơn vẫn đo lời nói; nó sẽ cho ra con số gần như cũ.',
      d:'9% vẫn là một nhóm thật, tập trung ở một khung giờ — bỏ đi là mất khách đang trả tiền.'} },
  { type:'calc', stem:'Khảo sát: 62% nói muốn ít đường. POS: 9% ly chọn ít đường. Khoảng lệch nói – làm là bao nhiêu điểm phần trăm?',
    unit:'điểm %', ans:53, tol:0.1, wrong:[[85.5,'NHAM_DIEM_PHAN_TRAM'],[6.9,'SAI_MAU_SO']], errors:['NHAM_DIEM_PHAN_TRAM','SAI_MAU_SO'],
    steps:['Khoảng lệch tính bằng điểm phần trăm = tỉ lệ nói − tỉ lệ làm.','62 − 9 = <b>53 điểm phần trăm</b>.'] },
  { type:'mcq', stem:'Vì sao câu hỏi "Bạn có muốn sống lành mạnh hơn không?" thường cho kết quả cao hơn hành vi thật?',
    options:[{k:'a',t:'Người trả lời chọn đáp án tốt đẹp theo hình ảnh bản thân'},{k:'b',t:'Người khảo sát cố tình chọn khách thích đồ lành mạnh'},
             {k:'c',t:'Khách trả lời vội nên bấm nhầm vào phương án đầu tiên'},{k:'d',t:'Đồ lành mạnh luôn đắt nên khách không đủ tiền mua'}],
    answer:'a', why:{a:'Đúng. Đây là thiên lệch mong muốn xã hội: nói điều "nên" thì không tốn gì.',
      b:'Có thể xảy ra, nhưng khoảng lệch vẫn xuất hiện cả khi chọn mẫu ngẫu nhiên.',
      c:'Bấm nhầm có xảy ra nhưng ngẫu nhiên, không giải thích được độ lệch luôn nghiêng về phía "tốt đẹp".',
      d:'Giá là một yếu tố, nhưng khoảng lệch vẫn có cả khi hai lựa chọn cùng giá.'} },
  { type:'mcq', stem:'Một hãng nước giặt thấy 70% khách nói "sẵn sàng trả thêm cho bao bì thân thiện môi trường". Bạn nên xem gì trước khi tăng giá?',
    options:[{k:'a',t:'Hỏi lại cùng nhóm khách bằng thang điểm chi tiết hơn'},{k:'b',t:'Xem đối thủ có đang làm bao bì xanh hay không'},
             {k:'c',t:'Tính chi phí bao bì mới để biết cần tăng bao nhiêu'},{k:'d',t:'Bán thử hai loại cạnh nhau, đo tỉ lệ chọn thật'}],
    answer:'d', why:{a:'Thang điểm chi tiết hơn vẫn đo lời nói, không đo việc móc ví.',
      b:'Đối thủ là thông tin hữu ích nhưng không trả lời được khách có thật sự trả thêm không.',
      c:'Chi phí cần tính, nhưng trước hết phải biết có ai mua ở giá mới.',
      d:'Đúng. Thử bán thật là cách rẻ nhất để đo hành vi thay vì mong muốn.'} },
  { type:'mcq', stem:'Nhóm 9% chọn ít đường tập trung vào khách văn phòng buổi sáng. Thông tin này hữu ích nhất cho quyết định nào?',
    options:[{k:'a',t:'Tăng giá toàn bộ dòng ít đường vì đó là khách có tiền'},{k:'b',t:'Đẩy dòng ít đường trong combo và bảng menu buổi sáng'},
             {k:'c',t:'Chạy quảng cáo ít đường cho mọi nhóm khách cả ngày'},{k:'d',t:'Chuyển toàn bộ cửa hàng sang mở cửa từ sáng sớm'}],
    answer:'b', why:{a:'Nhóm nhỏ và mới hình thành; tăng giá dễ làm mất luôn nhóm này.',
      b:'Đúng. Hành vi đã chỉ ra ai và khi nào — đặt sản phẩm đúng chỗ đó.',
      c:'Dàn trải cho mọi nhóm là bỏ qua đúng tín hiệu vừa tìm được.',
      d:'Đây là quyết định vận hành lớn, dữ kiện về một dòng đồ uống chưa đủ để biện minh.'} },
  { type:'mcq', stem:'Điều nào dưới đây là dữ liệu hành vi, không phải dữ liệu lời nói?',
    options:[{k:'a',t:'Điểm hài lòng 4,5/5 trong phiếu khảo sát sau mua'},{k:'b',t:'Tỉ lệ khách nói sẽ giới thiệu cho bạn bè'},
             {k:'c',t:'Số lần một khách đặt lại món trong ba tháng'},{k:'d',t:'Câu trả lời "sẽ mua lại" trong buổi phỏng vấn nhóm'}],
    answer:'c', why:{a:'Điểm hài lòng là khách tự đánh giá — vẫn là lời nói.',
      b:'Ý định giới thiệu là lời hứa, chưa phải việc giới thiệu thật.',
      c:'Đúng. Đặt lại là dấu vết đã xảy ra, ghi trong hệ thống đơn hàng.',
      d:'"Sẽ mua lại" là ý định; hành vi là lần mua lại có thật.'} },
  ]},

/* ------------------------------------------------------------------ 02 */
{ id:'B:ob05-02', skill:'insight', read:'7 phút', t:'Khách cầm lên rồi đặt xuống: kệ đang nói gì?',
  situation:'Bạn đứng quan sát kệ dầu gội ở một cửa hàng Guardian trong 2 giờ cuối tuần. Có 120 người đi qua lối, 48 người dừng lại trước kệ, 30 người cầm một chai lên xem, nhưng chỉ 9 người bỏ vào giỏ. Phần lớn người đặt chai xuống đều lật ra mặt sau đọc rồi mới đặt lại.',
  concept:{ name:'Phễu tại điểm bán: đi qua – dừng – cầm – mua',
    body:'Tại kệ, mỗi khách để lại một chuỗi hành vi có thể đếm: <b>đi qua</b>, <b>dừng lại</b> (kệ thu hút được mắt), <b>cầm lên</b> (sản phẩm gợi tò mò), <b>bỏ giỏ</b> (sản phẩm thuyết phục được). Rơi nhiều ở bước nào cho biết vấn đề nằm ở đâu: ít người dừng là vấn đề trưng bày; dừng nhiều mà ít cầm là mặt trước bao bì; cầm nhiều mà đặt xuống là thông tin mặt sau, giá hoặc dung tích. Cách khách đặt xuống — lật mặt sau, nhìn giá, so với chai bên cạnh — là manh mối rẻ nhất bạn có.' },
  example:'Tỉ lệ dừng 48/120 = 40%, khá tốt. Cầm lên 30/48 = 62,5%, bao bì mặt trước đang làm tốt. Nhưng mua chỉ 9/30 = 30% — chỗ rơi lớn nhất nằm sau khi cầm lên, đúng lúc khách lật mặt sau. Giả thuyết đáng kiểm: mặt sau khó đọc, không nói rõ dành cho loại tóc nào. Việc cần làm là sửa thông tin mặt sau và nhãn kệ, chứ không phải tăng ngân sách quảng cáo.',
  takeaway:'Đừng hỏi khách có thích không — hãy đếm họ rơi ở bước nào trước kệ.',
  apply:'Đứng 20 phút ở một kệ bất kỳ, đếm bốn con số đi qua – dừng – cầm – mua. Nói trong 60 giây bước nào rơi nhiều nhất và bạn đoán vì sao.',
  mistakes:['Chỉ nhìn doanh số cuối cùng, không biết khách rơi ở bước nào.','Thấy khách cầm lên nhiều liền kết luận sản phẩm hấp dẫn, quên đếm số đặt xuống.'],
  q:[
  { type:'mcq', stem:'Trước khi đọc bài: 30 người cầm chai dầu gội lên xem. Bạn đoán bao nhiêu người mua?',
    options:[{k:'a',t:'Khoảng 25 người, cầm lên là gần như đã quyết mua'},{k:'b',t:'Khoảng 20 người, chỉ vài người đổi ý'},
             {k:'c',t:'Khoảng 15 người, một nửa số người cầm lên'},{k:'d',t:'Khoảng 9 người, phần lớn đặt xuống sau khi đọc'}],
    answer:'d', why:{a:'Cầm lên chỉ là tò mò; trong tình huống có 21 người đặt xuống.',
      b:'Tỉ lệ rơi thật lớn hơn nhiều: chỉ 9/30 mua.',
      c:'Gần hơn nhưng vẫn cao; con số thật là 9, tức 30%.',
      d:'Đúng. 9/30 = 30%; phần lớn đặt xuống sau khi lật mặt sau.'} },
  { type:'mcq', stem:'Phễu cho thấy khách dừng và cầm lên tốt, nhưng rơi mạnh sau khi lật mặt sau. Bạn sửa gì trước?',
    options:[{k:'a',t:'Tăng ngân sách quảng cáo để kéo thêm người vào lối'},{k:'b',t:'Đổi màu mặt trước bao bì cho nổi bật hơn giữa các chai trên kệ'},
             {k:'c',t:'Làm rõ thông tin mặt sau và nhãn kệ: loại tóc, công dụng'},{k:'d',t:'Giảm giá 20% để bù cho tỉ lệ mua thấp'}],
    answer:'c', why:{a:'Thêm người vào lối không sửa được chỗ đang rơi — sau khi cầm lên.',
      b:'Mặt trước đang làm tốt việc kéo khách dừng và cầm lên; chỗ rơi là sau khi lật mặt sau.',
      c:'Đúng. Chỗ rơi lớn nhất trùng với lúc khách đọc mặt sau — sửa đúng điểm đó.',
      d:'Giảm giá có thể giúp nhưng tốn lãi, và chưa chắc giá là lý do khách đặt xuống.'} },
  { type:'calc', stem:'Trong 2 giờ: 48 người dừng trước kệ, 30 người cầm lên, 9 người mua. Tỉ lệ mua trên số người cầm lên là bao nhiêu phần trăm?',
    unit:'%', ans:30, tol:0.1, wrong:[[18.75,'SAI_MAU_SO'],[7.5,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Mẫu số là số người cầm lên, không phải số người dừng hay đi qua.','9 ÷ 30 = 0,3 = <b>30%</b>.'] },
  { type:'mcq', stem:'Ở một kệ khác, 200 người đi qua nhưng chỉ 20 người dừng lại. Vấn đề có khả năng nằm ở đâu?',
    options:[{k:'a',t:'Giá sản phẩm quá cao so với đối thủ cùng kệ'},{k:'b',t:'Vị trí hoặc cách trưng bày không kéo được mắt khách'},
             {k:'c',t:'Thông tin công dụng ở mặt sau khó hiểu nên khách không muốn dừng'},{k:'d',t:'Khách không tin chất lượng của thương hiệu'}],
    answer:'b', why:{a:'Giá chỉ thấy được sau khi đã dừng lại nhìn gần.',
      b:'Đúng. Rơi ở bước dừng là vấn đề thu hút mắt: vị trí, mảng màu, bảng kệ.',
      c:'Khách chưa dừng thì chưa đọc mặt sau; vấn đề nằm ở bước thu hút ánh mắt.',
      d:'Niềm tin quan trọng nhưng thường thể hiện ở bước cầm – mua, không phải bước dừng.'} },
  { type:'mcq', stem:'Bạn chỉ có 20 phút ở cửa hàng. Cách quan sát nào cho nhiều thông tin nhất về lý do khách đặt sản phẩm xuống?',
    options:[{k:'a',t:'Ghi lại khách nhìn vào đâu ngay trước khi đặt xuống'},{k:'b',t:'Hỏi nhân viên sản phẩm nào bán chạy nhất tháng'},
             {k:'c',t:'Chụp ảnh toàn bộ kệ để về phân tích sau'},{k:'d',t:'Đếm tổng số người vào cửa hàng trong 20 phút'}],
    answer:'a', why:{a:'Đúng. Điểm nhìn cuối cùng — giá, mặt sau, chai bên cạnh — là manh mối trực tiếp cho lý do bỏ.',
      b:'Nhân viên kể ấn tượng chung, không cho biết khách nhìn gì trước khi đặt chai của bạn xuống.',
      c:'Ảnh kệ không chứa hành vi của khách.',
      d:'Lượng khách vào cửa là đầu phễu, không giải thích chuyện đặt xuống.'} },
  { type:'mcq', stem:'Nhiều khách cầm chai của bạn lên rồi đặt xuống và cầm ngay chai đối thủ cạnh bên, xem nhãn giá. Giả thuyết nào đáng kiểm tra nhất?',
    options:[{k:'a',t:'Bao bì mặt trước của bạn kém hấp dẫn hơn đối thủ'},{k:'b',t:'Khách không biết thương hiệu của bạn là gì'},
             {k:'c',t:'Kệ đặt quá cao nên khách khó lấy sản phẩm'},{k:'d',t:'Khách đang so giá trên mỗi ml giữa hai chai'}],
    answer:'d', why:{a:'Khách đã cầm chai của bạn lên, tức mặt trước đã làm được việc của nó.',
      b:'Không biết thương hiệu thì ít khi cầm lên xem kỹ đến vậy.',
      c:'Khách đã lấy được chai; độ cao kệ không phải vấn đề.',
      d:'Đúng. Hành vi so nhãn giá ngay sau khi đặt xuống chỉ về phép so giá – dung tích.'} },
  { type:'mcq', stem:'Một đồng nghiệp đề xuất phát phiếu hỏi khách "Vì sao bạn không mua?" ngay tại kệ. Hạn chế lớn nhất của cách này là gì?',
    options:[{k:'a',t:'Phiếu hỏi tốn chi phí in và nhân sự đứng phát'},{k:'b',t:'Khách không kịp trả lời vì đang vội thanh toán'},
             {k:'c',t:'Khách đưa lý do nghe hợp lý, không phải lý do thật'},{k:'d',t:'Cửa hàng không cho phép khảo sát trong giờ đông'}],
    answer:'c', why:{a:'Chi phí có, nhưng không phải hạn chế về chất lượng dữ liệu.',
      b:'Mẫu ít là vấn đề phụ; kể cả khi khách trả lời, lý do họ nói thường không phải lý do thật.',
      c:'Đúng. Khách hợp lý hoá sau sự việc; hành vi quan sát được đáng tin hơn.',
      d:'Đây là trở ngại thủ tục, có thể xin phép; không phải hạn chế của phương pháp.'} },
  ]},

/* ------------------------------------------------------------------ 03 */
{ id:'B:ob05-03', skill:'measure', read:'7 phút', t:'Giỏ hàng bỏ dở: khách đổi ý hay bị chặn?',
  situation:'Một shop mỹ phẩm trên website riêng có 2.000 lượt thêm vào giỏ trong tháng, nhưng chỉ 600 đơn hoàn tất. Dữ liệu từng bước cho thấy: 2.000 người vào giỏ, 1.500 người bấm "Thanh toán", 1.400 người điền xong địa chỉ, rồi rơi mạnh xuống 600 ở bước hiện phí ship 35.000đ.',
  concept:{ name:'Giỏ hàng bỏ dở là tín hiệu, không phải rác',
    body:'Người thêm vào giỏ đã cho thấy ý định mua. Khi họ bỏ đi, câu hỏi đúng là <b>họ bỏ ở bước nào</b>. Rơi đều ở mọi bước thường là khách lướt, xem cho vui. Rơi dồn vào một bước cụ thể là dấu hiệu có <b>vật cản</b>: phí phát sinh bất ngờ, bắt tạo tài khoản, thiếu phương thức thanh toán quen. Vật cản sửa được bằng quy trình, rẻ hơn nhiều so với kéo thêm người mới vào đầu phễu.' },
  example:'Từ vào giỏ đến thanh toán: 1.500/2.000 = 75%. Điền địa chỉ: 1.400/1.500 ≈ 93%. Đến bước phí ship: 600/1.400 ≈ 43%. Bước phí ship mất 800 người — nhiều hơn tất cả các bước khác cộng lại (500 + 100). Phí ship hiện muộn khiến tổng tiền "nhảy" đúng lúc khách sắp trả. Thử nghiệm hợp lý: báo phí ship ngay ở trang sản phẩm, hoặc miễn phí ship từ ngưỡng giá trị đơn.',
  takeaway:'Tìm bước khách rơi dồn dập — đó là vật cản, sửa rẻ hơn mua thêm traffic.',
  apply:'Mở giỏ hàng của một sàn bạn hay dùng, đi tới bước cuối rồi dừng. Nói trong 60 giây: bước nào khiến bạn muốn bỏ nhất, vì sao.',
  mistakes:['Tính tỉ lệ bỏ giỏ tổng, không tách từng bước.','Gửi mã giảm giá cho mọi người bỏ giỏ thay vì gỡ vật cản.'],
  q:[
  { type:'mcq', stem:'Trước khi đọc bài: shop có 2.000 lượt vào giỏ mà chỉ 600 đơn. Bạn đoán khách rơi nhiều nhất ở đâu?',
    options:[{k:'a',t:'Ngay sau khi thêm vào giỏ, vì khách chỉ lưu để xem'},{k:'b',t:'Ở bước điền địa chỉ, vì mất công gõ nhiều'},
             {k:'c',t:'Ở bước lộ phí ship, vì tổng tiền tăng bất ngờ'},{k:'d',t:'Rải đều ở mọi bước, không có bước nào nổi trội'}],
    answer:'c', why:{a:'Có 500 người rơi ở đây — đáng kể nhưng không phải lớn nhất.',
      b:'Bước địa chỉ chỉ mất 100 người.',
      c:'Đúng. 800 người rơi ở bước phí ship, nhiều hơn các bước khác cộng lại.',
      d:'Số liệu cho thấy rơi dồn vào một bước, không đều.'} },
  { type:'mcq', stem:'Bạn có ngân sách một tháng để tăng số đơn. Bạn chọn làm gì trước?',
    options:[{k:'a',t:'Báo phí ship ngay trang sản phẩm, thử miễn ship từ ngưỡng đơn'},{k:'b',t:'Tăng ngân sách quảng cáo để có thêm lượt vào giỏ'},
             {k:'c',t:'Gửi mã giảm 10% cho tất cả người đã bỏ giỏ để kéo họ quay lại chốt đơn'},{k:'d',t:'Rút gọn form địa chỉ xuống còn hai ô nhập liệu'}],
    answer:'a', why:{a:'Đúng. Gỡ đúng vật cản đang làm mất 800 người mỗi tháng.',
      b:'Thêm người vào đầu phễu thì họ vẫn rơi ở cùng bước phí ship.',
      c:'Mã giảm tốn lãi cho cả người vốn sẽ mua, và không gỡ được cú sốc phí ship ở bước cuối.',
      d:'Bước địa chỉ chỉ mất 100 người; sửa nó lợi ích nhỏ.'} },
  { type:'calc', stem:'1.400 người điền xong địa chỉ, 600 người hoàn tất đơn sau khi thấy phí ship. Bao nhiêu phần trăm khách rơi ở bước phí ship? (làm tròn 1 chữ số thập phân)',
    unit:'%', ans:57.1, tol:0.2, wrong:[[40,'SAI_MAU_SO'],[42.9,'NHAM_TI_LE_ROI']], errors:['SAI_MAU_SO','NHAM_TI_LE_ROI'],
    steps:['Số người rơi = 1.400 − 600 = 800.','Tỉ lệ rơi = 800 ÷ 1.400 ≈ <b>57,1%</b> (mẫu số là số người vào bước đó, không phải 2.000).'] },
  { type:'mcq', stem:'Một shop khác thấy khách rơi đều khoảng 20% ở mọi bước thanh toán. Cách đọc nào hợp lý nhất?',
    options:[{k:'a',t:'Có một vật cản lớn ở bước cuối cần gỡ ngay'},{k:'b',t:'Trang thanh toán bị lỗi kỹ thuật ở mỗi bước một ít'},
             {k:'c',t:'Phí ship của shop cao hơn hẳn đối thủ trên sàn'},{k:'d',t:'Phần nhiều là khách lướt, chưa thấy vật cản nổi trội'}],
    answer:'d', why:{a:'Vật cản lớn sẽ tạo một bước rơi dồn, không phải rơi đều.',
      b:'Lỗi kỹ thuật thường gây rơi dồn ở một bước cụ thể, không đều ở mọi bước.',
      c:'Phí ship cao sẽ làm rơi dồn ở bước hiện phí, không rải đều.',
      d:'Đúng. Rơi đều là mẫu hình của khách chưa quyết, cần xem nguồn traffic hơn là quy trình.'} },
  { type:'mcq', stem:'Sau khi đưa phí ship lên trang sản phẩm, lượt vào giỏ giảm từ 2.000 xuống 1.700 nhưng số đơn tăng lên 750. Bạn đánh giá thế nào?',
    options:[{k:'a',t:'Thất bại, vì lượt vào giỏ đã giảm 15%'},{k:'b',t:'Thành công, người vào giỏ giờ là người chấp nhận phí thật'},
             {k:'c',t:'Chưa kết luận được vì số đơn chỉ tăng nhẹ'},{k:'d',t:'Thành công, nhưng nên giấu phí ship lại để vào giỏ tăng'}],
    answer:'b', why:{a:'Vào giỏ chỉ là bước trung gian; mục tiêu là đơn hoàn tất, và đơn đã tăng 25%.',
      b:'Đúng. Báo trước phí lọc bớt người sẽ bỏ, và số đơn thật tăng từ 600 lên 750.',
      c:'Tăng từ 600 lên 750 đơn là 25% — đủ rõ, và mục tiêu là đơn chứ không phải lượt vào giỏ.',
      d:'Giấu phí đưa vật cản trở lại cuối phễu; vào giỏ tăng nhưng đơn giảm.'} },
  { type:'mcq', stem:'Với khách bỏ giỏ ở bước phí ship, tin nhắn nhắc lại nào có khả năng hiệu quả nhất?',
    options:[{k:'a',t:'"Bạn quên gì trong giỏ hàng rồi kìa!"'},{k:'b',t:'"Sản phẩm sắp hết hàng, đặt ngay kẻo lỡ"'},
             {k:'c',t:'"Thêm 50.000đ nữa là được miễn phí ship"'},{k:'d',t:'"Cảm ơn bạn đã ghé thăm cửa hàng của chúng tôi"'}],
    answer:'c', why:{a:'Nhắc chung chung không chạm vào lý do bỏ là phí ship.',
      b:'Tạo khan hiếm không gỡ được cảm giác bị tính phí bất ngờ.',
      c:'Đúng. Tin nhắn nói thẳng vào vật cản vừa quan sát được.',
      d:'Lời cảm ơn không cho khách lý do quay lại thanh toán.'} },
  { type:'mcq', stem:'Dữ liệu cho thấy 30% khách bỏ giỏ lúc 23h–1h đêm và phần lớn quay lại mua vào sáng hôm sau. Nên hiểu hành vi này thế nào?',
    options:[{k:'a',t:'Khách dùng giỏ như danh sách lưu, quyết mua khi tỉnh táo'},{k:'b',t:'Website bị chậm vào ban đêm nên khách không thanh toán được'},
             {k:'c',t:'Khách đêm là nhóm không có ý định mua, nên bỏ qua'},{k:'d',t:'Cần gửi mã giảm giá lúc nửa đêm để chốt đơn ngay'}],
    answer:'a', why:{a:'Đúng. Đó là bỏ dở "tự nhiên", không phải vật cản — nhắc vào buổi sáng hợp hơn giảm giá.',
      b:'Nếu lỗi kỹ thuật, khách sẽ không quay lại mua đúng món đó sáng hôm sau.',
      c:'Họ có quay lại mua — gạt bỏ là bỏ qua khách thật.',
      d:'Họ vốn sẽ mua; giảm giá lúc này là trả tiền cho đơn đã chắc.'} },
  ]},

/* ------------------------------------------------------------------ 04 */
{ id:'B:ob05-04', skill:'insight', read:'6 phút', t:'Lượt tìm kiếm tăng vọt: nhu cầu thật hay cơn sốt?',
  situation:'Bạn làm cho một hãng đồ gia dụng. Trong Google Trends và thanh tìm kiếm TikTok, cụm "máy lọc không khí" ở Hà Nội tăng mạnh: chỉ số tháng 9 là 25, tháng 11 lên 100 khi mù không khí dày đặc. Cùng lúc, cụm "máy lọc không khí cho phòng ngủ nhỏ" tăng đều 20% mỗi năm trong ba năm liền.',
  concept:{ name:'Tìm kiếm là nhu cầu tự khai',
    body:'Khi gõ vào ô tìm kiếm, khách không trả lời ai cả — họ đang <b>tự giải quyết một vấn đề</b>. Vì vậy dữ liệu tìm kiếm gần với hành vi hơn khảo sát. Cần tách hai loại tín hiệu: <b>đỉnh theo mùa/sự kiện</b> (tăng vọt rồi rơi, lặp lại theo năm) và <b>xu hướng nền</b> (tăng đều qua nhiều năm). Cụm từ dài, cụ thể ("cho phòng ngủ nhỏ", "cho người dị ứng") còn cho biết khách đang ở gần quyết định mua và đang lo điều gì.' },
  example:'Chỉ số tăng từ 25 lên 100 là gấp 4 lần, nhưng xem lại hai năm trước thì năm nào tháng 11–1 cũng vọt rồi rơi vào tháng 4 — đó là đỉnh mùa ô nhiễm, nên chuẩn bị hàng và quảng cáo trước tháng 10. Còn cụm "phòng ngủ nhỏ" tăng đều 20%/năm cho thấy một nhu cầu nền đang lớn: nhà chung cư nhỏ, muốn máy êm và gọn. Đó là gợi ý cho dòng sản phẩm, không chỉ cho lịch quảng cáo.',
  takeaway:'Đỉnh tìm kiếm cho biết khi nào bán; xu hướng nền cho biết nên làm sản phẩm gì.',
  apply:'Chọn một ngành hàng, tra hai cụm từ trên Google Trends trong 5 năm. Nói trong 60 giây: cụm nào là đỉnh mùa, cụm nào là xu hướng nền.',
  mistakes:['Thấy tìm kiếm tăng vọt một tháng liền mở dòng sản phẩm mới.','Chỉ xem từ khoá ngắn chung chung, bỏ qua cụm dài cho biết khách lo điều gì.'],
  q:[
  { type:'mcq', stem:'Trước khi đọc bài: tìm kiếm "máy lọc không khí" tăng gấp 4 lần trong hai tháng. Bạn đoán điều gì đang xảy ra?',
    options:[{k:'a',t:'Một thương hiệu lớn vừa ra mắt sản phẩm mới'},{k:'b',t:'Đỉnh theo mùa ô nhiễm, lặp lại hằng năm'},
             {k:'c',t:'Thị trường máy lọc khí đang bùng nổ bền vững'},{k:'d',t:'Có một video viral làm người ta tò mò tìm'}],
    answer:'b', why:{a:'Ra mắt sản phẩm thường làm tăng tìm tên thương hiệu, không phải cả ngành hàng theo đúng mùa.',
      b:'Đúng. Dữ liệu các năm trước cho thấy năm nào tháng 11–1 cũng vọt rồi rơi.',
      c:'Bùng nổ bền vững sẽ không rơi lại vào tháng 4 mỗi năm.',
      d:'Video viral tạo đỉnh ngắn một lần, không lặp lại đúng mùa mỗi năm.'} },
  { type:'mcq', stem:'Sếp muốn nhập gấp gấp đôi hàng vào tháng 12 vì "tìm kiếm đang tăng gấp 4". Bạn đề xuất gì?',
    options:[{k:'a',t:'Nhập ngay gấp đôi để không lỡ đỉnh nhu cầu'},{k:'b',t:'Chờ thêm hai tháng xem xu hướng còn tăng không rồi mới quyết định nhập hàng'},
             {k:'c',t:'Lên kế hoạch hàng và quảng cáo từ tháng 10 cho các mùa sau'},{k:'d',t:'Chuyển toàn bộ ngân sách sang TikTok vì tìm kiếm tăng ở đó'}],
    answer:'c', why:{a:'Nhập tháng 12 là muộn; hàng về khi đỉnh sắp qua sẽ tồn sau tháng 4.',
      b:'Chờ thêm sẽ đúng lúc mùa đã qua; nhịp mùa vụ đã đủ rõ để lên kế hoạch sớm cho năm sau.',
      c:'Đúng. Đỉnh mùa đoán trước được — chuẩn bị trước đỉnh chứ không đuổi theo nó.',
      d:'Kênh tìm kiếm tăng không có nghĩa phải dồn hết tiền vào đó.'} },
  { type:'calc', stem:'Cụm "máy lọc không khí cho phòng ngủ nhỏ" có chỉ số 50 năm đầu và tăng đều 20% mỗi năm. Sau hai năm chỉ số là bao nhiêu?',
    unit:'điểm', ans:72, tol:0.1, wrong:[[70,'RETENTION_TUYEN_TINH'],[60,'SAI_TINH_TOAN']], errors:['RETENTION_TUYEN_TINH','SAI_TINH_TOAN'],
    steps:['Tăng 20% mỗi năm là nhân 1,2 mỗi năm, cộng dồn.','Năm 2: 50 × 1,2 = 60. Năm 3: 60 × 1,2 = <b>72</b>.'] },
  { type:'mcq', stem:'Cụm "máy lọc không khí cho người dị ứng lông mèo" tăng đều. Tín hiệu này hữu ích nhất cho việc gì?',
    options:[{k:'a',t:'Chọn khung giờ đăng bài trên mạng xã hội'},{k:'b',t:'Đặt ngân sách quảng cáo tổng cho cả năm dựa trên độ lớn của cụm từ khoá này'},
             {k:'c',t:'Tính giá bán lẻ đề xuất cho dòng máy mới'},{k:'d',t:'Viết thông điệp và tính năng nói đúng nỗi lo của khách'}],
    answer:'d', why:{a:'Cụm tìm kiếm không cho biết giờ khách lướt mạng.',
      b:'Cụm từ ngách này nhỏ về lượng; giá trị của nó nằm ở việc cho biết nỗi lo cụ thể của khách.',
      c:'Tìm kiếm không nói gì về mức giá khách chịu trả.',
      d:'Đúng. Cụm dài cho biết khách lo cụ thể điều gì — chất liệu cho thông điệp và sản phẩm.'} },
  { type:'mcq', stem:'Một hãng thấy tìm kiếm tên thương hiệu mình tăng 3 lần sau khi một KOL review. Hai tuần sau lại về mức cũ. Nên đọc thế nào?',
    options:[{k:'a',t:'Đỉnh ngắn do sự kiện; cần xem doanh số có giữ lại không'},{k:'b',t:'Thương hiệu đã tăng nhận biết gấp 3 lần một cách bền vững'},
             {k:'c',t:'KOL đó không hiệu quả vì tìm kiếm đã về mức cũ'},{k:'d',t:'Nên thuê lại KOL đó mỗi tháng để giữ tìm kiếm cao'}],
    answer:'a', why:{a:'Đúng. Tò mò ngắn hạn là bình thường; câu hỏi là có để lại khách mua lặp lại không.',
      b:'Về lại mức cũ sau hai tuần nghĩa là không bền.',
      c:'Đỉnh ngắn vẫn có thể mang lại đơn; kết luận cần dựa trên doanh số.',
      d:'Chưa biết đỉnh đó tạo ra đơn hay không thì chưa nên cam kết chi đều đặn.'} },
  { type:'mcq', stem:'Vì sao dữ liệu tìm kiếm thường đáng tin hơn câu trả lời khảo sát khi đo nhu cầu?',
    options:[{k:'a',t:'Vì mẫu tìm kiếm luôn lớn hơn mẫu khảo sát rất nhiều nên sai số gần như bằng 0'},{k:'b',t:'Vì Google và TikTok đã lọc sạch các lượt tìm giả'},
             {k:'c',t:'Vì khách tìm để tự giải quyết việc, không đóng vai cho ai'},{k:'d',t:'Vì người tìm kiếm luôn có ý định mua ngay lập tức'}],
    answer:'c', why:{a:'Mẫu lớn không sửa được thiên lệch; điểm mạnh thật là người tìm không đóng vai cho ai.',
      b:'Dữ liệu tìm kiếm vẫn có nhiễu; đó không phải lý do cốt lõi.',
      c:'Đúng. Không có người hỏi nên không có thiên lệch "trả lời cho đẹp".',
      d:'Nhiều lượt tìm chỉ là tìm hiểu; ý định mua thể hiện rõ hơn ở cụm dài, cụ thể.'} },
  { type:'mcq', stem:'Trên TikTok, người dùng tìm "review máy lọc không khí có ồn không" nhiều hơn "máy lọc không khí giá rẻ". Hàm ý nào hợp lý nhất?',
    options:[{k:'a',t:'Khách không quan tâm giá, có thể tăng giá thoải mái'},{k:'b',t:'Độ ồn là nỗi lo lớn, nên chứng minh độ êm trong nội dung'},
             {k:'c',t:'TikTok không phải kênh phù hợp để bán máy lọc'},{k:'d',t:'Nên làm video so sánh giá với tất cả đối thủ vì khách đang cân nhắc mua'}],
    answer:'b', why:{a:'Ít tìm "giá rẻ" không có nghĩa khách thờ ơ với giá.',
      b:'Đúng. Câu hỏi khách tự gõ cho biết họ sợ điều gì — nội dung nên trả lời đúng điều đó.',
      c:'Có người tìm review trên TikTok nghĩa là kênh này có vai trò trong quyết định.',
      d:'Khách đang tìm về độ ồn nhiều hơn giá; video so giá trả lời sai câu hỏi.'} },
  ]},

/* ------------------------------------------------------------------ 05 */
{ id:'B:ob05-05', skill:'channel', read:'6 phút', t:'Bình luận livestream toàn hỏi giá: khách đang bảo bạn gì?',
  situation:'Một shop đồ bộ mặc nhà livestream trên TikTok Shop mỗi tối. Bạn xuất 400 bình luận của phiên gần nhất và phân loại: 160 câu hỏi về size ("cao 1m55 nặng 50kg mặc size gì"), 90 câu hỏi giá, 60 câu hỏi chất vải có nóng không, 90 bình luận chào hỏi, thả tim. Đơn chốt trong phiên: 120.',
  concept:{ name:'Câu hỏi của khách là bản đồ rào cản',
    body:'Trong livestream, khách không điền phiếu — họ hỏi đúng điều đang <b>ngăn họ bấm mua</b>. Đếm và gom nhóm câu hỏi cho biết rào cản nào lớn nhất. Câu hỏi lặp đi lặp lại là dấu hiệu thông tin đó đang thiếu ở trang sản phẩm và trong kịch bản live. Mỗi rào cản được trả lời sẵn là một lý do bớt đi để khách rời phiên mà không mua.' },
  example:'Trong 310 bình luận có nội dung câu hỏi, size chiếm 160, tức khoảng 52% — rào cản số một. Giá chỉ 90 câu, và giá vốn đã hiện trên giỏ hàng, nên nhiều người hỏi giá thật ra là hỏi "có rẻ hơn không". Việc nên làm: dựng bảng size theo chiều cao – cân nặng ghim lên màn hình, cho người mẫu cỡ khác nhau mặc thử, và đưa bảng đó vào ảnh sản phẩm.',
  takeaway:'Câu khách hỏi nhiều nhất trong live là thông tin bạn còn thiếu ở trang bán.',
  apply:'Mở một phiên livestream bất kỳ, ghi lại 30 bình luận đầu tiên và gom nhóm. Nói trong 60 giây: rào cản lớn nhất của khách là gì.',
  mistakes:['Trả lời từng câu hỏi một mà không đếm để thấy câu nào lặp lại.','Coi lượng bình luận là thước đo thành công, không nhìn nội dung.'],
  q:[
  { type:'mcq', stem:'Trước khi đọc bài: trong livestream bán đồ bộ, bạn đoán khách hỏi nhiều nhất về điều gì?',
    options:[{k:'a',t:'Giá và mã giảm giá riêng của phiên'},{k:'b',t:'Chất vải mặc có nóng hay xù lông không'},
             {k:'c',t:'Thời gian giao hàng và phí ship về tỉnh'},{k:'d',t:'Size nào vừa với chiều cao, cân nặng'}],
    answer:'d', why:{a:'Giá được hỏi, nhưng câu hỏi size áp đảo.',
      b:'Chất vải có được hỏi, nhưng ít hơn nhiều so với câu hỏi về size.',
      c:'Có người hỏi, nhưng ít hơn hẳn câu hỏi về size.',
      d:'Đúng. 160 câu về size — gần gấp đôi câu hỏi giá.'} },
  { type:'mcq', stem:'Phiên sau bạn chỉ được thay đổi một thứ. Bạn chọn sửa gì?',
    options:[{k:'a',t:'Ghim bảng size theo chiều cao – cân nặng lên màn hình'},{k:'b',t:'Giảm giá sâu hơn để trả lời gọn các câu hỏi giá'},
             {k:'c',t:'Mời thêm một host nói nhanh để đọc kịp bình luận'},{k:'d',t:'Kéo dài phiên live thêm một giờ để có nhiều đơn hơn'}],
    answer:'a', why:{a:'Đúng. Gỡ rào cản lớn nhất cho hàng trăm người cùng lúc, không phải trả lời từng người.',
      b:'Giá chỉ là rào cản thứ hai, và giảm giá tốn lãi.',
      c:'Đọc kịp vẫn phải trả lời lặp lại cùng câu; ghim bảng size trả lời một lần cho tất cả.',
      d:'Kéo dài phiên không sửa lý do khách đang ngần ngừ.'} },
  { type:'calc', stem:'Trong 310 bình luận là câu hỏi, có 160 câu về size. Câu hỏi size chiếm bao nhiêu phần trăm số câu hỏi? (làm tròn 1 chữ số thập phân)',
    unit:'%', ans:51.6, tol:0.2, wrong:[[40,'SAI_MAU_SO'],[133.3,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Mẫu số là số câu hỏi (310), không phải tổng 400 bình luận hay số đơn 120.','160 ÷ 310 ≈ <b>51,6%</b>.'] },
  { type:'mcq', stem:'Phiên livestream có 2.000 bình luận nhưng phần lớn là "chào shop", thả tim, và chỉ 40 đơn. Kết luận nào hợp lý?',
    options:[{k:'a',t:'Phiên rất thành công vì tương tác cao gấp nhiều lần'},{k:'b',t:'Khách không thích sản phẩm nên chỉ vào chào cho vui'},
             {k:'c',t:'Tương tác cao nhưng ít câu hỏi mua — sức mua yếu'},{k:'d',t:'Cần thêm mini game để bình luận còn tăng lên nữa'}],
    answer:'c', why:{a:'Số bình luận không phải doanh số; nội dung bình luận mới là tín hiệu.',
      b:'Không có dữ kiện về việc khách không thích; họ có thể chưa có nhu cầu.',
      c:'Đúng. Ít câu hỏi về size, giá, chất liệu nghĩa là ít người đang cân nhắc mua.',
      d:'Tăng bình luận kiểu chào hỏi không đổi được sức mua.'} },
  { type:'mcq', stem:'Nhiều khách hỏi "vải này mặc có nóng không" dù trang sản phẩm đã ghi "cotton 100%". Nên hiểu thế nào?',
    options:[{k:'a',t:'Khách lười đọc, không cần làm gì thêm'},{k:'b',t:'Thông tin kỹ thuật chưa trả lời được cảm giác khi mặc'},
             {k:'c',t:'Cần đổi sang chất liệu khác mát hơn ngay lập tức'},{k:'d',t:'Nên ghi chữ "cotton 100%" to và đậm hơn nữa'}],
    answer:'b', why:{a:'Khi nhiều người cùng hỏi, vấn đề là cách trình bày, không phải khách.',
      b:'Đúng. Khách cần biết "có mát không", nên chỉ cho họ thấy — ví dụ quay cảnh mặc ngày nắng.',
      c:'Chưa có dữ kiện cho thấy vải nóng thật; khách chỉ đang hỏi.',
      d:'Khách đã thấy chữ cotton; họ hỏi cảm giác khi mặc, điều mà thông số không trả lời.'} },
  { type:'mcq', stem:'Bạn muốn biết rào cản mua của một sản phẩm mới trước khi làm trang bán. Nguồn nào gần với hành vi thật nhất?',
    options:[{k:'a',t:'Câu hỏi khách để lại dưới livestream của đối thủ bán món tương tự'},{k:'b',t:'Ý kiến của đội sales trong buổi họp nội bộ'},
             {k:'c',t:'Phiếu khảo sát online có quà tặng để nhiều người chịu trả lời thật lòng về rào cản'},{k:'d',t:'Báo cáo xu hướng ngành của một công ty nghiên cứu'}],
    answer:'a', why:{a:'Đúng. Đó là câu hỏi thật của người đang cân nhắc mua đúng loại hàng này.',
      b:'Đội sales có kinh nghiệm nhưng đây là suy đoán qua trung gian.',
      c:'Quà tăng số người trả lời, không làm câu trả lời gần hành vi thật hơn.',
      d:'Báo cáo ngành rộng, ít khi đi tới rào cản của một món cụ thể.'} },
  { type:'mcq', stem:'Sau khi ghim bảng size, câu hỏi size giảm từ 160 xuống 40 và đơn tăng từ 120 lên 150. Điều nên làm tiếp là gì?',
    options:[{k:'a',t:'Gỡ bảng size ra vì câu hỏi đã giảm, không còn cần'},{k:'b',t:'Dừng phân loại bình luận vì đã tìm được vấn đề chính'},
             {k:'c',t:'Quay lại tập trung giảm giá vì size đã được xử lý'},{k:'d',t:'Đếm lại bình luận để tìm rào cản lớn nhất tiếp theo'}],
    answer:'d', why:{a:'Câu hỏi giảm chính là nhờ bảng size; gỡ đi thì rào cản quay lại.',
      b:'Rào cản thay đổi theo sản phẩm và thời gian; cần đọc liên tục.',
      c:'Chưa biết giá có phải rào cản số một mới không; phải đếm lại.',
      d:'Đúng. Gỡ xong một rào cản thì rào cản kế tiếp lộ ra — lặp lại vòng đếm.'} },
  ]},

/* ------------------------------------------------------------------ 06 */
{ id:'B:ob05-06', skill:'measure', read:'7 phút', t:'Khách khen ngon mà không quay lại: tin lời khen hay tin lịch sử đơn?',
  situation:'Một tiệm bánh mì ở Đà Nẵng mở đơn trên app giao đồ ăn. Điểm đánh giá 4,8 sao, bình luận toàn khen "ngon, sẽ ủng hộ tiếp". Nhưng trong 1.000 khách đặt lần đầu tháng 3, chỉ 150 người đặt lại trong tháng 4, và 90 người còn đặt tiếp trong tháng 5. Tiệm bên cạnh 4,5 sao có tỉ lệ đặt lại tháng sau là 35%.',
  concept:{ name:'Tỉ lệ quay lại theo nhóm (cohort retention)',
    body:'Lời khen là điều khách nói lúc vừa ăn xong. <b>Quay lại mua</b> là điều khách làm khi có lựa chọn khác. Cách đo sạch nhất là theo dõi một nhóm khách có cùng tháng mua đầu (cohort) và xem bao nhiêu phần trăm còn mua ở các tháng sau. Tỉ lệ quay lại thấp dù điểm cao thường có nghĩa: món ngon nhưng không đủ lý do để chọn lại — giá, phí ship, thời gian giao, hoặc không nằm trong thói quen hằng ngày.' },
  example:'Tháng 4 còn 150/1.000 = 15% quay lại, tháng 5 còn 90/1.000 = 9%. Tiệm bên cạnh điểm thấp hơn nhưng giữ được 35% — đó mới là tiệm đang thắng trong thói quen của khách. Việc cần làm là tìm vì sao 850 người không quay lại: so phí ship, thời gian giao, giá combo buổi sáng với tiệm bên cạnh, thay vì tiếp tục đuổi theo điểm sao.',
  takeaway:'Điểm sao đo cảm xúc một lần; tỉ lệ quay lại đo chỗ đứng trong thói quen.',
  apply:'Nhìn lại 10 quán bạn từng khen trong năm qua. Nói trong 60 giây: bao nhiêu quán bạn quay lại hơn hai lần, và lý do thật là gì.',
  mistakes:['Dùng điểm đánh giá trung bình thay cho tỉ lệ quay lại.','Tính tỉ lệ quay lại tháng sau chia cho số khách tháng trước đó thay vì nhóm gốc ban đầu.'],
  q:[
  { type:'mcq', stem:'Trước khi đọc bài: tiệm 4,8 sao và tiệm 4,5 sao cạnh nhau. Bạn đoán tiệm nào giữ khách quay lại tốt hơn?',
    options:[{k:'a',t:'Tiệm 4,8 sao, vì khách hài lòng hơn rõ rệt'},{k:'b',t:'Hai tiệm gần như ngang nhau vì điểm chênh ít'},
             {k:'c',t:'Tiệm 4,5 sao, dù điểm thấp hơn'},{k:'d',t:'Không thể đoán vì hai tiệm bán món khác nhau'}],
    answer:'c', why:{a:'Điểm cao không bảo đảm quay lại; tiệm 4,8 chỉ giữ 15%.',
      b:'Chênh lệch quay lại rất lớn: 15% so với 35%.',
      c:'Đúng. Tiệm 4,5 sao giữ 35% khách tháng sau, hơn gấp đôi.',
      d:'Cả hai cùng bán bánh mì trên cùng app, so được.'} },
  { type:'mcq', stem:'Chủ tiệm muốn chạy chương trình tặng quà để khách đánh giá 5 sao nhiều hơn. Bạn đề xuất gì?',
    options:[{k:'a',t:'Làm ngay, vì điểm cao giúp lên top tìm kiếm trên app và kéo thêm khách mới'},{k:'b',t:'Tìm lý do 85% khách không đặt lại: phí ship, giá, giờ giao'},
             {k:'c',t:'Giảm giá 30% cho mọi đơn để kéo thật nhiều khách mới'},{k:'d',t:'Thay đổi công thức bánh để ngon hơn nữa'}],
    answer:'b', why:{a:'Điểm sao đã cao; khách mới vào nhiều mà không ở lại thì thêm sao không giải quyết được.',
      b:'Đúng. Hành vi cho thấy rào cản nằm sau lần mua đầu — tìm nó trước.',
      c:'Kéo khách mới vào một cái xô thủng: 85% vẫn rời đi.',
      d:'Khách đã khen ngon; vị không phải lý do chính khiến họ bỏ.'} },
  { type:'calc', stem:'Nhóm 1.000 khách mua lần đầu tháng 3. Tháng 5 còn 90 người đặt. Tỉ lệ quay lại tháng 5 của nhóm này là bao nhiêu phần trăm?',
    unit:'%', ans:9, tol:0.1, wrong:[[60,'SAI_MAU_SO'],[85,'NHAM_TI_LE_ROI']], errors:['SAI_MAU_SO','NHAM_TI_LE_ROI'],
    steps:['Tỉ lệ quay lại theo cohort luôn chia cho nhóm gốc ban đầu.','90 ÷ 1.000 = <b>9%</b> (không chia cho 150 người tháng 4).'] },
  { type:'mcq', stem:'Một quán cà phê có 3.000 khách mới mỗi tháng nhưng tổng số khách hoạt động không tăng suốt nửa năm. Điều gì có khả năng xảy ra?',
    options:[{k:'a',t:'Quán đang giữ khách rất tốt nên không cần thêm khách mới'},{k:'b',t:'Số liệu khách mới bị đếm trùng giữa các tháng'},
             {k:'c',t:'Thị trường đã bão hoà nên không thể tăng thêm'},{k:'d',t:'Khách cũ rời đi nhanh gần bằng tốc độ khách mới vào'}],
    answer:'d', why:{a:'Nếu giữ khách tốt, 3.000 khách mới mỗi tháng sẽ làm tổng số tăng lên.',
      b:'Có thể, nhưng mẫu hình này thường là do rời bỏ cao.',
      c:'Vẫn có 3.000 khách mới mỗi tháng — thị trường chưa bão hoà.',
      d:'Đúng. Tổng đứng yên khi rời bỏ bằng thu hút — dấu hiệu tỉ lệ quay lại thấp.'} },
  { type:'mcq', stem:'Vì sao nên so tỉ lệ quay lại theo từng nhóm tháng mua đầu, thay vì một con số trung bình chung?',
    options:[{k:'a',t:'Để thấy thay đổi gần đây có làm khách mới ở lại tốt hơn không'},{k:'b',t:'Vì trung bình chung đã đủ, chia nhóm chỉ để báo cáo trông chuyên nghiệp hơn'},
             {k:'c',t:'Vì app giao đồ ăn chỉ cung cấp dữ liệu theo tháng'},{k:'d',t:'Vì con số trung bình chung luôn bị tính sai'}],
    answer:'a', why:{a:'Đúng. Mỗi cohort phản ánh trải nghiệm ở thời điểm đó; trung bình chung che mất thay đổi.',
      b:'Trung bình chung trộn khách cũ và mới, che mất tác động của thay đổi gần đây.',
      c:'Nguồn dữ liệu không phải lý do về phương pháp.',
      d:'Trung bình chung không sai, chỉ trộn lẫn các nhóm nên khó đọc thay đổi.'} },
  { type:'mcq', stem:'Nhóm khách tháng 6 (sau khi tiệm giảm phí ship) quay lại 28%, so với 15% của nhóm tháng 3. Bạn kết luận thận trọng thế nào?',
    options:[{k:'a',t:'Phí ship chắc chắn là nguyên nhân duy nhất khách bỏ'},{k:'b',t:'Giảm phí ship có khả năng giúp; cần theo dõi thêm vài nhóm'},
             {k:'c',t:'Không kết luận được gì vì điểm sao không đổi'},{k:'d',t:'Tháng 6 là mùa hè nên khách tự nhiên quay lại nhiều hơn'}],
    answer:'b', why:{a:'Một lần so sánh chưa đủ để gọi là nguyên nhân duy nhất.',
      b:'Đúng. Tín hiệu mạnh, nhưng cần vài nhóm nữa để loại yếu tố mùa vụ.',
      c:'Điểm sao không phải thước đo quay lại; kết luận dựa vào cohort.',
      d:'Mùa có thể góp phần, nên cần theo dõi thêm; nhưng quy hết cho mùa là vội vàng.'} },
  { type:'mcq', stem:'Bình luận "sẽ ủng hộ tiếp" xuất hiện trong 70% đánh giá. Nên dùng con số này thế nào?',
    options:[{k:'a',t:'Như dự báo rằng khoảng 70% khách sẽ quay lại mua tiếp'},{k:'b',t:'Như bằng chứng tiệm không cần cải thiện gì'},
             {k:'c',t:'Như tín hiệu thiện cảm, không phải dự báo mua lại'},{k:'d',t:'Như lý do để tăng giá bán thêm 10%'}],
    answer:'c', why:{a:'Lời hứa trong đánh giá là thiện cảm, không phải hành vi; tỉ lệ quay lại thật thấp hơn nhiều.',
      b:'Hành vi cho thấy 85% không quay lại; rõ ràng cần cải thiện.',
      c:'Đúng. Đó là thiện cảm thật, nhưng dự báo mua lại phải dựa vào dữ liệu đơn.',
      d:'Lời khen không cho biết khách chịu giá cao hơn; có thể càng ít quay lại.'} },
  ]},

/* ------------------------------------------------------------------ 07 */
{ id:'B:ob05-07', skill:'channel', read:'6 phút', t:'Giờ nào khách thật sự mua, và bạn đang quảng cáo giờ nào?',
  situation:'Một thương hiệu cơm văn phòng giao tận nơi ở TP.HCM chạy quảng cáo đều từ 8h đến 22h, ngân sách chia đều 14 giờ. Dữ liệu đơn một tháng: 4.200 đơn, trong đó 2.940 đơn đặt trong khung 10h–11h30. Buổi tối 19h–22h chiếm ngân sách lớn nhưng chỉ có 210 đơn.',
  concept:{ name:'Nhịp thói quen: giờ cao điểm là khi nhu cầu tự xuất hiện',
    body:'Khách không mua đều cả ngày. Nhu cầu nổi lên theo <b>nhịp sinh hoạt</b>: đói lúc gần trưa, lướt mua sắm sau giờ làm, chốt đơn ngày lương. Dữ liệu đơn theo giờ, theo thứ trong tuần cho biết nhịp đó. Quảng cáo đặt trùng nhịp thì gặp người đang có nhu cầu; đặt lệch nhịp thì phải trả tiền để thuyết phục người chưa cần. Nhịp khác nhau theo ngành hàng: cơm trưa khác mỹ phẩm, khác đồ gia dụng.' },
  example:'2.940/4.200 = 70% đơn nằm trong 1,5 giờ buổi trưa. Buổi tối 3 giờ chỉ 210 đơn = 5%, nhưng đang nhận khoảng 3/14 ≈ 21% ngân sách. Cách chỉnh: dồn phần lớn ngân sách vào 9h30–11h30 để bắt người đang đói, giữ một ít buổi tối cho thông điệp đặt trước cơm ngày mai — một nhu cầu khác, cần thử và đo riêng.',
  takeaway:'Đặt quảng cáo theo nhịp khách tự có nhu cầu, không chia đều theo đồng hồ.',
  apply:'Xem lại lịch sử đơn của bạn trên một app giao đồ ăn hoặc sàn. Nói trong 60 giây: bạn hay mua vào giờ nào, thứ mấy, và vì sao.',
  mistakes:['Chia ngân sách đều theo giờ vì "không biết khách lúc nào".','Thấy buổi tối ít đơn liền kết luận buổi tối vô dụng, không thử thông điệp khác phù hợp nhịp tối.'],
  q:[
  { type:'mcq', stem:'Trước khi đọc bài: với cơm văn phòng giao tận nơi, bạn đoán bao nhiêu phần trăm đơn rơi vào khung 10h–11h30?',
    options:[{k:'a',t:'Khoảng 70%, vì gần trưa là lúc mọi người đói'},{k:'b',t:'Khoảng 30%, vì khách đặt rải rác cả ngày'},
             {k:'c',t:'Khoảng 50%, số còn lại chia đều cho buổi sáng sớm và buổi tối'},{k:'d',t:'Khoảng 10%, vì phần lớn đặt từ tối hôm trước'}],
    answer:'a', why:{a:'Đúng. 2.940/4.200 = 70% — nhu cầu dồn vào một khung ngắn.',
      b:'Nhu cầu ăn trưa không rải đều; dữ liệu cho thấy tập trung mạnh.',
      c:'Dữ liệu đơn cho thấy khung gần trưa chiếm phần lớn hơn nhiều, khoảng 70%.',
      d:'Đặt từ tối trước chỉ có 210 đơn, rất nhỏ.'} },
  { type:'mcq', stem:'Ngân sách tháng tới không đổi. Bạn chọn phân bổ thế nào?',
    options:[{k:'a',t:'Giữ chia đều 14 giờ để không bỏ sót khách nào'},{k:'b',t:'Cắt hẳn quảng cáo buổi sáng, dồn hết vào buổi tối vì lúc đó ít đối thủ chạy'},
             {k:'c',t:'Chuyển hết ngân sách sang một kênh quảng cáo khác'},{k:'d',t:'Dồn phần lớn vào 9h30–11h30, giữ ít để thử đặt trước buổi tối'}],
    answer:'d', why:{a:'Chia đều là trả nhiều tiền cho giờ ít người cần.',
      b:'Buổi tối rẻ vì ít người đặt; bỏ khung đơn nhiều nhất là bỏ phần lớn doanh thu.',
      c:'Vấn đề là thời điểm chứ không phải kênh.',
      d:'Đúng. Theo nhịp nhu cầu, vẫn giữ một thử nghiệm nhỏ để học thêm.'} },
  { type:'calc', stem:'Quảng cáo chia đều 14 giờ (8h–22h). Khung 19h–22h (3 giờ) nhận bao nhiêu phần trăm ngân sách? (làm tròn 1 chữ số thập phân)',
    unit:'%', ans:21.4, tol:0.2, wrong:[[5,'NHAM_SO_TUYET_DOI'],[30,'SAI_MAU_SO']], errors:['NHAM_SO_TUYET_DOI','SAI_MAU_SO'],
    steps:['Ngân sách chia đều theo giờ nên tỉ lệ = số giờ khung ÷ tổng số giờ.','3 ÷ 14 ≈ <b>21,4%</b> ngân sách, trong khi chỉ mang về 5% đơn.'] },
  { type:'mcq', stem:'Một shop mỹ phẩm trên Shopee thấy đơn tăng vọt vào ngày 25 hằng tháng và các ngày đôi như 10/10. Nhịp này nói gì?',
    options:[{k:'a',t:'Khách chỉ có nhu cầu dùng mỹ phẩm vào cuối tháng và các ngày lễ đôi'},{k:'b',t:'Khách chờ ngày có lương và ngày sàn có khuyến mãi lớn'},
             {k:'c',t:'Shop đang bị lỗi hiển thị vào các ngày khác'},{k:'d',t:'Khách mua theo mùa thời tiết nóng lạnh'}],
    answer:'b', why:{a:'Mỹ phẩm dùng hằng ngày; thứ đổi theo ngày là thời điểm khách chịu xuống tiền.',
      b:'Đúng. Ngày lương và ngày đôi là nhịp mua đã thành thói quen trên sàn.',
      c:'Lỗi hiển thị không lặp đúng ngày 25 và ngày đôi mỗi tháng.',
      d:'Thời tiết không thay đổi theo ngày 25 hay ngày đôi.'} },
  { type:'mcq', stem:'Buổi tối ít đơn cơm trưa. Thông điệp nào hợp với nhịp buổi tối nhất để thử?',
    options:[{k:'a',t:'"Đói rồi? Cơm nóng giao trong 20 phút"'},{k:'b',t:'"Giảm 50% cho mọi đơn cơm đặt ngay bây giờ"'},
             {k:'c',t:'"Đặt trước cơm trưa mai, khỏi lo trưa ăn gì"'},{k:'d',t:'"Thương hiệu cơm văn phòng số 1 thành phố"'}],
    answer:'c', why:{a:'Buổi tối khách không đói cơm văn phòng; thông điệp lệch nhịp.',
      b:'Buổi tối khách không đói cơm trưa; giảm sâu cũng khó tạo đơn và tốn lãi.',
      c:'Đúng. Buổi tối là lúc lên kế hoạch cho ngày mai — thông điệp khớp nhu cầu lúc đó.',
      d:'Lời tự khen không gắn với nhu cầu nào ở khung giờ này.'} },
  { type:'mcq', stem:'Vì sao dữ liệu đơn theo giờ đáng tin hơn câu hỏi "Bạn thường đặt cơm lúc mấy giờ?"',
    options:[{k:'a',t:'Vì khách hay nói giờ họ nghĩ là hợp lý, không phải giờ thật'},{k:'b',t:'Vì câu hỏi khảo sát luôn có quá nhiều phương án khiến khách chọn bừa'},
             {k:'c',t:'Vì dữ liệu đơn được app kiểm toán mỗi tháng'},{k:'d',t:'Vì khách không nhớ mình đã từng đặt cơm'}],
    answer:'a', why:{a:'Đúng. Ước lượng thói quen của chính mình thường lệch; dấu thời gian đơn thì không.',
      b:'Số phương án không phải gốc vấn đề; khách nói giờ họ nghĩ là hợp lý, không phải giờ thật.',
      c:'Kiểm toán không liên quan; dữ liệu đơn tốt vì ghi lại hành vi thật.',
      d:'Khách nhớ là có đặt, nhưng không ước đúng giờ và tần suất.'} },
  { type:'mcq', stem:'Đơn trưa thứ Hai – thứ Sáu đều cao, nhưng thứ Bảy giảm 80%. Quyết định nào hợp lý?',
    options:[{k:'a',t:'Tăng quảng cáo thứ Bảy gấp đôi để kéo đơn lên bằng ngày thường'},{k:'b',t:'Đóng cửa cả tuần vì doanh số không đều'},
             {k:'c',t:'Giữ nguyên, vì biến động theo thứ là ngẫu nhiên'},{k:'d',t:'Giảm ngân sách và nhân sự thứ Bảy theo đúng nhịp văn phòng'}],
    answer:'d', why:{a:'Thứ Bảy khách văn phòng không đi làm; tiền quảng cáo khó tạo ra nhu cầu đó.',
      b:'Ngày thường vẫn bán tốt; đóng cửa là phản ứng quá tay.',
      c:'Giảm 80% đều đặn mỗi tuần là một mẫu hình, không ngẫu nhiên.',
      d:'Đúng. Vận hành và ngân sách đi theo nhịp mà dữ liệu đã chỉ ra.'} },
  ]},

/* ------------------------------------------------------------------ 08 */
{ id:'B:ob05-08', skill:'insight', read:'7 phút', t:'Khách chọn COD rồi bom hàng: đó là tín hiệu gì?',
  situation:'Một shop thời trang trên Facebook và website nhận 1.000 đơn một tháng, 80% chọn thanh toán khi nhận (COD). Tỉ lệ hoàn đơn COD là 25%, còn đơn chuyển khoản trước chỉ hoàn 3%. Mỗi đơn hoàn làm shop mất 40.000đ phí giao đi – về. Chủ shop muốn bắt buộc chuyển khoản trước cho mọi đơn.',
  concept:{ name:'Phương thức thanh toán là tín hiệu niềm tin',
    body:'Khách chọn COD không phải vì thích tiền mặt, mà vì <b>chưa đủ tin</b>: sợ hàng không giống ảnh, sợ shop biến mất. Trả sau, trả góp, ví điện tử cũng là tín hiệu — về dòng tiền và về mức rủi ro khách chấp nhận. Đọc phương thức thanh toán theo nhóm khách, nhóm sản phẩm cho biết chỗ nào niềm tin còn yếu. Ép bỏ COD thường làm mất nhiều đơn thật hơn số đơn hoàn tránh được; tốt hơn là xây niềm tin để khách tự chọn trả trước.' },
  example:'800 đơn COD × 25% = 200 đơn hoàn, mất 200 × 40.000đ = 8 triệu đồng mỗi tháng. Nhưng nếu bắt chuyển khoản mà một nửa khách COD bỏ đi, shop mất 400 đơn. Cách làm có căn cứ: giảm 15.000đ cho đơn trả trước, cho xem hàng trước khi nhận, gọi xác nhận đơn COD giá trị lớn — rồi đo tỉ lệ hoàn và tỉ lệ trả trước sau một tháng.',
  takeaway:'COD và bom hàng đo độ tin của khách — sửa niềm tin trước khi siết luật thanh toán.',
  apply:'Nhớ lại lần gần nhất bạn chọn COD. Nói trong 60 giây: bạn sợ điều gì, và điều gì sẽ khiến bạn chịu trả trước.',
  mistakes:['Coi khách COD là khách xấu và loại bỏ họ.','Chỉ tính chi phí đơn hoàn, quên tính số đơn mất đi khi bỏ COD.'],
  q:[
  { type:'mcq', stem:'Trước khi đọc bài: bạn đoán lý do chính khiến khách mua online ở Việt Nam chọn COD là gì?',
    options:[{k:'a',t:'Khách không có tài khoản ngân hàng để chuyển'},{k:'b',t:'Khách chưa tin shop, muốn thấy hàng mới trả tiền'},
             {k:'c',t:'Khách muốn giữ tiền mặt để chi tiêu tiện hơn'},{k:'d',t:'Phí chuyển khoản ngân hàng quá cao'}],
    answer:'b', why:{a:'Phần lớn khách mua online đều có cách chuyển tiền; lý do chính là chưa tin shop.',
      b:'Đúng. COD là cách khách tự chuyển rủi ro sang người bán.',
      c:'Thói quen tiền mặt có, nhưng không giải thích được chênh lệch hoàn đơn.',
      d:'Chuyển khoản nội địa phần lớn miễn phí.'} },
  { type:'mcq', stem:'Chủ shop muốn bắt buộc chuyển khoản trước cho mọi đơn. Bạn đề xuất gì?',
    options:[{k:'a',t:'Làm ngay, vì sẽ tiết kiệm được 8 triệu mỗi tháng'},{k:'b',t:'Tăng giá mọi sản phẩm để bù chi phí đơn hoàn mà vẫn giữ nguyên COD'},
             {k:'c',t:'Giữ COD, thêm ưu đãi trả trước và xác nhận đơn lớn, rồi đo'},{k:'d',t:'Chặn số điện thoại của mọi khách từng hoàn đơn'}],
    answer:'c', why:{a:'Tiết kiệm 8 triệu nhưng có thể mất hàng trăm đơn thật.',
      b:'Tăng giá làm mất khách cho cả người nhận hàng tử tế, trong khi vấn đề hoàn đơn vẫn còn.',
      c:'Đúng. Xây niềm tin để khách tự chuyển sang trả trước, và đo kết quả.',
      d:'Có thể dùng cho khách bom nhiều lần, nhưng không giải quyết được gốc là niềm tin.'} },
  { type:'calc', stem:'Shop có 800 đơn COD mỗi tháng, tỉ lệ hoàn 25%, mỗi đơn hoàn mất 40.000đ phí giao đi – về. Chi phí đơn hoàn mỗi tháng là bao nhiêu triệu đồng?',
    unit:'triệu đồng', ans:8, tol:0.05, wrong:[[10,'SAI_MAU_SO'],[32,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO','SAI_TINH_TOAN'],
    steps:['Số đơn hoàn = 800 × 25% = 200 đơn (tính trên đơn COD, không phải 1.000 đơn).','Chi phí = 200 × 40.000đ = 8.000.000đ = <b>8 triệu đồng</b>.'] },
  { type:'mcq', stem:'Tỉ lệ hoàn COD của áo 150.000đ là 10%, còn của váy dạ hội 1.200.000đ là 35%. Cách đọc nào hợp lý nhất?',
    options:[{k:'a',t:'Váy dạ hội bị lỗi chất lượng nên khách từ chối nhận'},{k:'b',t:'Khách mua váy là nhóm khách xấu, nên bỏ qua'},
             {k:'c',t:'Áo rẻ nên khách không quan tâm có nhận hay không'},{k:'d',t:'Món giá cao thì rủi ro cảm nhận cao, khách dễ đổi ý hơn'}],
    answer:'d', why:{a:'Không có dữ liệu cho thấy lỗi hàng; tỉ lệ hoàn cao theo giá là dấu hiệu của rủi ro cảm nhận.',
      b:'Đó vẫn là khách có nhu cầu thật với món giá trị cao.',
      c:'Tỉ lệ hoàn thấp ở áo là do rủi ro thấp, không phải thờ ơ.',
      d:'Đúng. Món đắt cần thêm bằng chứng: ảnh thật, video, cho thử trước khi nhận.'} },
  { type:'mcq', stem:'Nhiều khách chọn "Mua trước trả sau" cho điện thoại nhưng không cho ốp lưng. Tín hiệu này nói gì?',
    options:[{k:'a',t:'Khách chia nhỏ khoản lớn để giữ dòng tiền, không vì thiếu tin'},{k:'b',t:'Khách không tin người bán điện thoại nên chỉ dám trả sau từng phần nhỏ'},
             {k:'c',t:'Ốp lưng đang bị đặt giá quá cao'},{k:'d',t:'Tính năng trả sau đang bị lỗi với ốp lưng'}],
    answer:'a', why:{a:'Đúng. Trả sau là tín hiệu về dòng tiền với món giá trị lớn.',
      b:'Nếu thiếu tin thì họ đã chọn COD; trả sau là cách chia nhỏ khoản lớn để giữ dòng tiền.',
      c:'Ốp lưng rẻ, không cần chia nhỏ — không liên quan đến định giá.',
      d:'Không có dữ kiện về lỗi; mẫu hình hợp lý theo giá trị đơn.'} },
  { type:'mcq', stem:'Sau một tháng thêm ưu đãi trả trước 15.000đ, tỉ lệ đơn trả trước tăng từ 20% lên 45%, tổng đơn không đổi. Kết luận nào đúng?',
    options:[{k:'a',t:'Ưu đãi thất bại vì tổng đơn không tăng'},{k:'b',t:'Nên tăng ưu đãi lên 50.000đ để kéo nốt số khách còn lại sang trả trước'},
             {k:'c',t:'Ưu đãi chuyển được khách sang trả trước mà không mất đơn'},{k:'d',t:'Nên bỏ hẳn COD vì khách đã sẵn sàng trả trước'}],
    answer:'c', why:{a:'Mục tiêu là giảm hoàn đơn mà giữ đơn — đã đạt được.',
      b:'Ưu đãi hiện tại đã hiệu quả; tăng thêm tốn lãi cho nhóm vốn sẽ không bao giờ bỏ COD.',
      c:'Đúng. Khách đổi hành vi thanh toán, đơn giữ nguyên — ít đơn hoàn hơn.',
      d:'Vẫn còn 55% khách chọn COD; bỏ đi là mất họ.'} },
  { type:'mcq', stem:'Một thương hiệu mới bán qua TikTok Shop thấy 90% đơn chọn COD, cao hơn hẳn mức 60% của các shop lâu năm cùng ngành. Nên ưu tiên việc gì?',
    options:[{k:'a',t:'Hạ giá xuống thấp hơn các shop lâu năm để bù cho việc chưa có đánh giá'},{k:'b',t:'Tăng tín hiệu tin cậy: đánh giá thật, video mở hộp, chính sách đổi trả'},
             {k:'c',t:'Chuyển hết sang bán trên website riêng'},{k:'d',t:'Tắt COD để buộc khách trả trước, giống các shop lâu năm đang làm để giảm hoàn'}],
    answer:'b', why:{a:'Giá rẻ hơn không bù được thiếu tin; khách vẫn sợ mua phải hàng kém.',
      b:'Đúng. COD cao là tín hiệu thiếu niềm tin — gỡ đúng điểm đó.',
      c:'Website riêng của thương hiệu mới thường còn ít niềm tin hơn.',
      d:'Shop mới chưa có lòng tin; tắt COD sẽ đẩy khách sang shop lâu năm.'} },
  ]},

/* ------------------------------------------------------------------ 09 */
{ id:'B:ob05-09', skill:'insight', read:'6 phút', t:'Khách mở ba sàn so giá: bạn nên đua giá hay đua thứ khác?',
  situation:'Một thương hiệu sữa rửa mặt bán trên Shopee, Lazada và TikTok Shop với cùng giá niêm yết 189.000đ. Qua theo dõi, 60% khách xem sản phẩm trên cả hai sàn trở lên trước khi mua. Khi một sàn có mã giảm 20.000đ, đơn chuyển hẳn sang sàn đó; nhưng khi giá ngang nhau, 70% khách chọn sàn giao nhanh nhất.',
  concept:{ name:'So giá đa sàn: khách so tổng giá trị, không chỉ con số',
    body:'Hành vi mở nhiều tab so giá cho biết khách <b>coi sản phẩm là giống nhau ở mọi nơi</b> — họ chỉ chọn nơi mua. Điều họ so thật sự là <b>tổng chi phí và rủi ro</b>: giá sau mã, phí ship, thời gian giao, hàng chính hãng hay không, đổi trả dễ không. Khi giá ngang nhau, yếu tố khác quyết định. Thương hiệu cần đọc khách đổi sàn vì yếu tố nào trước khi lao vào đua giảm giá.' },
  example:'Mã 20.000đ trên giá 189.000đ là giảm khoảng 10,6% — đủ để kéo đơn sang sàn khác, nghĩa là khách rất nhạy với chênh lệch giá. Nhưng khi giá bằng nhau, 70% chọn giao nhanh. Quyết định hợp lý: giữ giá đồng nhất giữa các sàn để không ai phải săn, và đầu tư vào kho gần, giao nhanh, gian hàng chính hãng — thứ đối thủ khó sao chép bằng một mã giảm.',
  takeaway:'Khách so giá để chọn nơi mua; giữ giá đồng nhất và thắng bằng giao nhanh, tin cậy.',
  apply:'Chọn một món bạn định mua, mở hai sàn và ghi lại mọi thứ bạn so. Nói trong 60 giây: yếu tố nào cuối cùng quyết định.',
  mistakes:['Thấy khách so giá liền giảm giá trên mọi sàn, tự đua với chính mình.','Để giá lệch giữa các sàn, khiến khách quen phải đi săn và mất lòng tin.'],
  q:[
  { type:'mcq', stem:'Trước khi đọc bài: khi giá sữa rửa mặt bằng nhau trên các sàn, bạn đoán khách chọn sàn theo tiêu chí nào nhiều nhất?',
    options:[{k:'a',t:'Sàn có nhiều đánh giá sản phẩm nhất'},{k:'b',t:'Sàn mà khách quen dùng lâu nhất'},
             {k:'c',t:'Sàn có ảnh sản phẩm đẹp nhất'},{k:'d',t:'Sàn giao hàng nhanh nhất'}],
    answer:'d', why:{a:'Đánh giá quan trọng, nhưng dữ liệu cho thấy giao nhanh quyết định 70%.',
      b:'Thói quen có tác động, nhưng không phải tiêu chí số một ở đây.',
      c:'Ảnh sản phẩm giống nhau vì cùng một thương hiệu.',
      d:'Đúng. Khi giá ngang, 70% khách chọn sàn giao nhanh nhất.'} },
  { type:'mcq', stem:'Đối thủ vừa giảm giá 15% trên Shopee. Bạn chọn phản ứng thế nào?',
    options:[{k:'a',t:'Giảm ngay 20% trên mọi sàn để chắc chắn rẻ nhất'},{k:'b',t:'Giữ giá, đẩy mạnh giao nhanh và nhãn chính hãng, theo dõi đơn'},
             {k:'c',t:'Tăng giá để định vị thương hiệu cao cấp hơn, tách hẳn khỏi cuộc đua giá'},{k:'d',t:'Rút khỏi Shopee vì cạnh tranh giá quá gắt'}],
    answer:'b', why:{a:'Đua giá xuống làm mỏng lãi, đối thủ có thể giảm tiếp.',
      b:'Đúng. Dữ liệu cho thấy khi giá gần nhau, giao nhanh thắng — đánh vào đó và đo.',
      c:'Tăng giá khi khách đang so giá dễ mất đơn; lợi thế thật là giao nhanh và chính hãng.',
      d:'Rút khỏi sàn lớn là bỏ luôn lượng khách đang có.'} },
  { type:'calc', stem:'Giá niêm yết 189.000đ, một sàn có mã giảm 20.000đ. Mức giảm tương đương bao nhiêu phần trăm? (làm tròn 1 chữ số thập phân)',
    unit:'%', ans:10.6, tol:0.1, wrong:[[11.8,'SAI_MAU_SO'],[20,'NHAM_SO_TUYET_DOI']], errors:['SAI_MAU_SO','NHAM_SO_TUYET_DOI'],
    steps:['Mức giảm % = tiền giảm ÷ giá gốc trước giảm.','20.000 ÷ 189.000 ≈ 0,106 = <b>10,6%</b> (không chia cho giá sau giảm 169.000đ).'] },
  { type:'mcq', stem:'Vì sao để giá lệch nhau nhiều giữa các sàn có thể làm hại thương hiệu?',
    options:[{k:'a',t:'Khách quen phải đi săn giá và nghi ngờ giá niêm yết'},{k:'b',t:'Các sàn sẽ phạt thương hiệu vì giá không đồng nhất'},
             {k:'c',t:'Chi phí vận hành tăng vì phải quản lý nhiều mức giá'},{k:'d',t:'Đối thủ sẽ dễ dàng theo dõi và sao chép chiến lược giá từng sàn của bạn'}],
    answer:'a', why:{a:'Đúng. Khi giá lệch, khách học cách chờ và săn — giá niêm yết mất ý nghĩa.',
      b:'Thường không có quy định phạt như vậy; rủi ro chính nằm ở hành vi khách.',
      c:'Có tốn công, nhưng không phải tác hại lớn nhất.',
      d:'Đối thủ vốn thấy giá của bạn; rủi ro lớn hơn là khách quen mất niềm tin vào giá niêm yết.'} },
  { type:'mcq', stem:'Một khách xem sản phẩm trên TikTok Shop qua video, nhưng lại sang Shopee đặt mua. Hành vi này gợi ý gì?',
    options:[{k:'a',t:'Video TikTok không hiệu quả, nên dừng làm video'},{k:'b',t:'Khách nhầm lẫn giữa hai ứng dụng nên vô tình đặt đơn trên Shopee'},
             {k:'c',t:'TikTok tạo nhu cầu, Shopee là nơi khách tin để chốt đơn'},{k:'d',t:'Shopee đang rẻ hơn TikTok rất nhiều'}],
    answer:'c', why:{a:'Video đã làm được việc khơi nhu cầu; chỉ là đơn chốt ở nơi khác.',
      b:'Khách chủ động chuyển sang Shopee; đó là chọn nơi tin tưởng, không phải nhầm.',
      c:'Đúng. Mỗi sàn đóng một vai trong hành trình; đo đơn riêng từng sàn sẽ đánh giá thấp TikTok.',
      d:'Tình huống cho giá niêm yết như nhau; không có dữ kiện chênh lớn.'} },
  { type:'mcq', stem:'Bạn muốn biết khách so gì giữa các sàn cho dòng kem chống nắng. Cách nào gần hành vi thật nhất?',
    options:[{k:'a',t:'Khảo sát khách "Bạn quan tâm nhất điều gì khi chọn sàn để mua hàng?"'},{k:'b',t:'Hỏi đội chăm sóc khách hàng về ấn tượng chung'},
             {k:'c',t:'Đọc báo cáo xu hướng thương mại điện tử năm nay'},{k:'d',t:'So tỉ lệ chọn sàn khi thay đổi lần lượt giá, phí ship, giờ giao'}],
    answer:'d', why:{a:'Khách nói điều nghe hợp lý; cần quan sát lựa chọn thật khi các yếu tố thay đổi.',
      b:'Ấn tượng của đội chăm sóc là gián tiếp, dễ lệch về ca khó.',
      c:'Báo cáo chung không cho biết khách của bạn so gì.',
      d:'Đúng. Đổi một yếu tố, xem khách dịch chuyển — đo hành vi trực tiếp.'} },
  { type:'mcq', stem:'Khi mã giảm 20.000đ xuất hiện ở Lazada, đơn Shopee giảm nhưng tổng đơn ba sàn gần như không đổi. Nên hiểu mã giảm này thế nào?',
    options:[{k:'a',t:'Mã giảm đã tạo thêm nhiều khách mới cho thương hiệu trên sàn Lazada'},{k:'b',t:'Mã giảm chủ yếu chuyển khách giữa các sàn, không tạo thêm đơn'},
             {k:'c',t:'Lazada có tệp khách chất lượng hơn Shopee'},{k:'d',t:'Shopee đang gặp sự cố kỹ thuật trong thời gian đó'}],
    answer:'b', why:{a:'Tổng đơn không tăng; đơn Lazada tăng đúng bằng phần Shopee giảm.',
      b:'Đúng. Mã giảm kéo khách đổi chỗ mua; thương hiệu mất 20.000đ mỗi đơn mà không bán thêm.',
      c:'Khách là cùng một nhóm, chỉ đổi sàn theo mã.',
      d:'Đơn giảm trùng đúng lúc có mã ở sàn khác, lý giải hợp lý hơn sự cố.'} },
  ]},

/* ------------------------------------------------------------------ 10 */
{ id:'B:ob05-10', skill:'measure', read:'7 phút', t:'Dữ liệu đơn cũ biết khách sắp mua lại khi nào?',
  situation:'Một shop bán thức ăn cho mèo trên website có 2.000 khách đã mua ít nhất hai lần. Họ đang gửi tin nhắn khuyến mãi cho tất cả vào mỗi thứ Sáu. Xem lại lịch sử đơn, bạn thấy khoảng cách giữa hai lần mua của phần lớn khách mua túi 2kg là 28–32 ngày, còn túi 5kg là 70–75 ngày.',
  concept:{ name:'Chu kỳ mua lại: dấu vết thói quen trong dữ liệu đơn',
    body:'Với hàng dùng hết rồi mua lại (thức ăn thú cưng, sữa, tã, mỹ phẩm), mỗi khách để lại một <b>nhịp mua</b> trong lịch sử đơn. Khoảng cách giữa hai đơn cho biết khi nào khách sắp hết hàng. Nhắn đúng trước thời điểm đó thì trúng nhu cầu; nhắn đều đặn cho mọi người thì phần lớn tin đến khi khách chưa cần, dễ bị coi là làm phiền. Khách trễ nhịp quá lâu là tín hiệu sắp rời bỏ — cần hỏi thăm hơn là giảm giá.' },
  example:'Khách túi 2kg mua lại sau khoảng 30 ngày, nên nhắc vào ngày thứ 25 kể từ đơn trước. Khách túi 5kg nhắc vào ngày 65. Gửi đều mỗi thứ Sáu nghĩa là một khách 2kg nhận khoảng 4 tin mỗi chu kỳ mà chỉ 1 tin rơi đúng lúc cần, tức khoảng 75% tin nhắn gửi lệch nhịp. Khách nào quá 45 ngày chưa mua lại túi 2kg thì đánh dấu rủi ro rời bỏ để gọi hỏi thăm.',
  takeaway:'Nhịp mua trong lịch sử đơn cho biết khi nào nhắc — đúng lúc hơn nhiều lần.',
  apply:'Mở lịch sử đơn của bạn với một món dùng hằng ngày. Nói trong 60 giây: chu kỳ mua lại của bạn là bao lâu, và shop có nhắc đúng lúc không.',
  mistakes:['Gửi khuyến mãi theo lịch cố định cho mọi khách, bất kể nhịp mua.','Chờ khách bỏ hẳn mới liên hệ, thay vì để ý khi họ trễ nhịp.'],
  q:[
  { type:'mcq', stem:'Trước khi đọc bài: shop nhắn khuyến mãi mỗi thứ Sáu cho mọi khách. Bạn đoán vấn đề lớn nhất là gì?',
    options:[{k:'a',t:'Phần lớn tin đến khi khách chưa cần mua lại'},{k:'b',t:'Thứ Sáu là ngày khách ít đọc tin nhắn nhất'},
             {k:'c',t:'Khuyến mãi mỗi tuần làm mất quá nhiều lãi'},{k:'d',t:'Tin nhắn quá dài nên khách không đọc hết'}],
    answer:'a', why:{a:'Đúng. Với chu kỳ 30 ngày, khoảng 3/4 số tin rơi vào lúc khách còn hàng.',
      b:'Ngày gửi có ảnh hưởng nhỏ; gốc vấn đề là tin đến khi khách chưa cần mua.',
      c:'Lãi có bị ảnh hưởng, nhưng gốc rễ là gửi lệch nhịp nhu cầu.',
      d:'Tình huống không nói gì về độ dài tin nhắn.'} },
  { type:'mcq', stem:'Bạn được làm lại lịch nhắn tin. Bạn chọn cách nào?',
    options:[{k:'a',t:'Tăng lên hai tin mỗi tuần để không bỏ lỡ ai'},{k:'b',t:'Chuyển sang nhắn mỗi đầu tháng cho tất cả khách'},
             {k:'c',t:'Chỉ nhắn cho khách mua túi 5kg vì đơn giá cao hơn và họ trung thành hơn hẳn'},{k:'d',t:'Nhắc từng khách theo nhịp mua riêng, trước ngày dự kiến hết hàng'}],
    answer:'d', why:{a:'Gửi dày hơn chỉ tăng số tin lệch nhịp và độ phiền.',
      b:'Lịch cố định mới vẫn không khớp nhịp từng khách.',
      c:'Bỏ nhóm túi nhỏ mất nhiều khách; thứ cần sửa là thời điểm nhắc, không phải đối tượng.',
      d:'Đúng. Dùng dấu vết đơn để nhắc đúng lúc nhu cầu xuất hiện.'} },
  { type:'calc', stem:'Chu kỳ mua lại túi 2kg khoảng 28 ngày, shop gửi 1 tin mỗi tuần. Trong một chu kỳ, chỉ 1 tin rơi đúng lúc khách sắp hết hàng. Bao nhiêu phần trăm số tin gửi lệch nhịp?',
    unit:'%', ans:75, tol:0.5, wrong:[[25,'NHAM_TI_LE_ROI'],[300,'SAI_MAU_SO']], errors:['NHAM_TI_LE_ROI','SAI_MAU_SO'],
    steps:['Số tin mỗi chu kỳ = 28 ÷ 7 = 4 tin.','Tin lệch nhịp = 4 − 1 = 3; tỉ lệ = 3 ÷ 4 = <b>75%</b>.'] },
  { type:'mcq', stem:'Một khách thường mua túi 2kg mỗi 30 ngày, nay đã 50 ngày chưa mua lại. Phản ứng nào hợp lý nhất?',
    options:[{k:'a',t:'Chờ thêm vì có thể khách đang bận'},{k:'b',t:'Gửi ngay mã giảm 30% để kéo lại trước khi khách chuyển hẳn sang shop khác'},
             {k:'c',t:'Hỏi thăm ngắn: mèo còn ăn hợp không, có cần đổi vị không'},{k:'d',t:'Xoá khách khỏi danh sách vì coi như đã rời bỏ'}],
    answer:'c', why:{a:'Trễ gần gấp đôi nhịp quen là tín hiệu rủi ro, chờ thêm dễ mất hẳn.',
      b:'Chưa biết lý do trễ mà đã giảm sâu thì tốn lãi; hỏi thăm trước để hiểu chuyện gì xảy ra.',
      c:'Đúng. Trễ nhịp là tín hiệu; hỏi thăm để hiểu lý do trước khi dùng tiền.',
      d:'Khách chưa chắc đã rời bỏ; xoá là tự đóng cửa.'} },
  { type:'mcq', stem:'Vì sao dữ liệu đơn cho biết thói quen tốt hơn câu hỏi "Bao lâu bạn mua thức ăn cho mèo một lần?"',
    options:[{k:'a',t:'Vì khách không muốn tiết lộ thông tin cá nhân'},{k:'b',t:'Vì khách thường đoán tròn số, lệch với nhịp mua thật'},
             {k:'c',t:'Vì câu hỏi khảo sát bị luật cấm dùng trong bán hàng'},{k:'d',t:'Vì dữ liệu đơn luôn đầy đủ, không bao giờ thiếu'}],
    answer:'b', why:{a:'Khách không ngại chia sẻ nhịp mua; vấn đề là họ đoán tròn số, lệch với nhịp mua thật.',
      b:'Đúng. Người ta hay nói "khoảng một tháng" dù thực tế là 25 hoặc 40 ngày.',
      c:'Không có lệnh cấm như vậy.',
      d:'Dữ liệu đơn có thể thiếu (khách mua nơi khác), nhưng vẫn là hành vi thật.'} },
  { type:'mcq', stem:'Nhiều khách từng mua túi 2kg đều đặn nay chuyển sang túi 5kg. Tín hiệu này gợi ý điều gì cho shop?',
    options:[{k:'a',t:'Khách đang tìm cách tiết kiệm hoặc nhà có thêm mèo'},{k:'b',t:'Túi 2kg đang bị lỗi chất lượng cần thu hồi'},
             {k:'c',t:'Khách chuẩn bị ngừng mua nên mua dự trữ lần cuối'},{k:'d',t:'Giá túi 5kg đang quá rẻ, shop cần tăng ngay'}],
    answer:'a', why:{a:'Đúng. Đổi sang gói lớn là tín hiệu về giá trị hoặc nhu cầu tăng — cập nhật nhịp nhắc theo 70 ngày.',
      b:'Không có dữ kiện về lỗi; khách vẫn mua cùng hãng.',
      c:'Người sắp rời bỏ hiếm khi mua túi to hơn; chuyển size thường là tiết kiệm hoặc nhà có thêm mèo.',
      d:'Chuyển gói là hành vi bình thường; chưa đủ căn cứ để đổi giá.'} },
  { type:'mcq', stem:'Một chuỗi tã bỉm muốn áp dụng nhắc theo nhịp mua. Điều gì cần lưu ý riêng với ngành này?',
    options:[{k:'a',t:'Nhịp mua tã không đổi theo thời gian nên đặt một lần là xong'},{k:'b',t:'Chỉ nên nhắc khách mua gói to vì họ trung thành hơn'},
             {k:'c',t:'Tã là hàng thiết yếu nên không cần nhắc khách'},{k:'d',t:'Bé lớn nhanh nên size và nhịp đổi; phải cập nhật theo đơn gần nhất'}],
    answer:'d', why:{a:'Nhịp và size thay đổi theo tuổi bé; đặt một lần là sai dần.',
      b:'Bỏ nhóm gói nhỏ mất khách; vấn đề là nhịp thay đổi theo tuổi bé, không phải cỡ gói.',
      c:'Thiết yếu không có nghĩa khách mua ở chỗ bạn; nhắc đúng lúc giữ họ lại.',
      d:'Đúng. Dấu vết đơn gần nhất phản ánh nhu cầu hiện tại tốt hơn lịch cũ.'} },
  ]},

]});
